def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def has_orthogonal_object(r, c):
        return any(
            0 <= r + dr < h and 0 <= c + dc < w
            and grid[r + dr][c + dc] != background
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))
        )

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == background:
                    continue

                # Only process the first cell of a contiguous diagonal run.
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                cells = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr, cc))
                    rr += dr
                    cc += dc

                if len(cells) < 2:
                    continue

                # Lines embedded at both ends in the small motif are not rays.
                if has_orthogonal_object(*cells[0]) and has_orthogonal_object(*cells[-1]):
                    continue

                for er, ec, sr, sc in (
                    (cells[0][0], cells[0][1], -dr, -dc),
                    (cells[-1][0], cells[-1][1], dr, dc),
                ):
                    rr, cc = er + sr, ec + sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc

    return out
